
/*
 * ChatCompletionStreamResponseDelta.h
 *
 * A chat completion delta generated by streamed model responses.
 */

#ifndef TINY_CPP_CLIENT_ChatCompletionStreamResponseDelta_H_
#define TINY_CPP_CLIENT_ChatCompletionStreamResponseDelta_H_


#include <string>
#include "bourne/json.hpp"
#include "Helpers.h"
#include "ChatCompletionMessageToolCallChunk.h"
#include "ChatCompletionStreamResponseDelta_function_call.h"
#include <list>

namespace Tiny {


/*! \brief A chat completion delta generated by streamed model responses.
 *
 *  \ingroup Models
 *
 */

class ChatCompletionStreamResponseDelta{
public:

    /*! \brief Constructor.
	 */
    ChatCompletionStreamResponseDelta();
    ChatCompletionStreamResponseDelta(std::string jsonString);


    /*! \brief Destructor.
	 */
    virtual ~ChatCompletionStreamResponseDelta();


    /*! \brief Retrieve a bourne JSON representation of this class.
	 */
    bourne::json toJson();


    /*! \brief Fills in members of this class from bourne JSON object representing it.
	 */
    void fromJson(std::string jsonObj);

	/*! \brief Get The contents of the chunk message.
	 */
	std::string getContent();

	/*! \brief Set The contents of the chunk message.
	 */
	void setContent(std::string  content);
	/*! \brief Get 
	 */
	ChatCompletionStreamResponseDelta_function_call getFunctionCall();

	/*! \brief Set 
	 */
	void setFunctionCall(ChatCompletionStreamResponseDelta_function_call  function_call);
	/*! \brief Get 
	 */
	std::list<ChatCompletionMessageToolCallChunk> getToolCalls();

	/*! \brief Set 
	 */
	void setToolCalls(std::list <ChatCompletionMessageToolCallChunk> tool_calls);
	/*! \brief Get The role of the author of this message.
	 */
	std::string getRole();

	/*! \brief Set The role of the author of this message.
	 */
	void setRole(std::string  role);
	/*! \brief Get The refusal message generated by the model.
	 */
	std::string getRefusal();

	/*! \brief Set The refusal message generated by the model.
	 */
	void setRefusal(std::string  refusal);


    private:
    std::string content{};
    ChatCompletionStreamResponseDelta_function_call function_call;
    std::list<ChatCompletionMessageToolCallChunk> tool_calls;
    std::string role{};
    std::string refusal{};
};
}

#endif /* TINY_CPP_CLIENT_ChatCompletionStreamResponseDelta_H_ */
